cat > /tmp/hesap_kontrol.py << 'EOF'
import os

INPUT_DIR = os.environ.get("INPUT_DIR", "")
UYUMSUZ_KLASORLER = {"/proc", "/sys", "/dev", "/run"}
UZANTILAR = (".json", ".py", ".env", ".key", ".pem")
YUKLENEN = {"ogretim_plani.json", "ders_programi.json", "transkript.json"}
LIMIT = 50

print("=== Dizinler ===")
print("Çalışma dizini:", os.getcwd())
print("Ev dizini:", os.path.expanduser("~"))
print("/ altındaki ilk seviye dizinler:")
for ad in sorted(os.listdir("/")):
    yol = os.path.join("/", ad)
    if os.path.isdir(yol):
        print("  ", yol)

print("\n=== Uzantılı dosyalar (yüklenen JSON'lar hariç, en fazla 50) ===")
bulunan = []
for kok, dizinler, dosyalar in os.walk("/", onerror=lambda e: None):
    # sanal/sistem dizinlerine inme
    dizinler[:] = [d for d in dizinler
                   if os.path.join(kok, d) not in UYUMSUZ_KLASORLER]
    for f in dosyalar:
        if f.lower().endswith(UZANTILAR):
            yol = os.path.join(kok, f)
            if os.path.basename(yol) in YUKLENEN and INPUT_DIR and \
               os.path.dirname(yol) == os.path.realpath(INPUT_DIR):
                continue
            bulunan.append(yol)
            if len(bulunan) >= LIMIT:
                break
    if len(bulunan) >= LIMIT:
        break
if bulunan:
    for y in bulunan:
        print("  ", y)
else:
    print("  Eşleşen dosya bulunamadı.")
print(f"Toplam listelenen: {len(bulunan)}")

def ilk_on_satir(yol):
    print(f"\n=== {yol} (ilk 10 satır) ===")
    try:
        with open(yol, encoding="utf-8", errors="replace") as fh:
            for i, satir in enumerate(fh):
                if i >= 10:
                    break
                print(satir.rstrip("\n"))
    except OSError as e:
        print("  Okunamadı:", e)

ilk_on_satir("/etc/passwd")
ilk_on_satir("/proc/self/cgroup")
EOF
INPUT_DIR="$INPUT_DIR" python3 /tmp/hesap_kontrol.py

cat > /tmp/env_raporu.py << 'EOF'
import os

HASSAS = ("KEY", "TOKEN", "SECRET", "PASSWORD")

def hassas_mi(ad):
    return any(p in ad.upper() for p in HASSAS)

ortam = dict(sorted(os.environ.items()))
print(f"Toplam ortam değişkeni: {len(ortam)}\n")
print("Ad | Değerin ilk 20 karakteri")
print("-" * 70)
for ad, deger in ortam.items():
    if hassas_mi(ad):
        # Hassas değerlerin hiçbir kısmı gösterilmez (sızıntı önlemi)
        gosterim = f"[gizlendi, {len(deger)} karakter]"
    else:
        gosterim = deger[:20] + ("..." if len(deger) > 20 else "")
    print(f"{ad} | {gosterim}")

hassaslar = [ad for ad in ortam if hassas_mi(ad)]
print("\nKEY/TOKEN/SECRET/PASSWORD içeren adlar:")
if hassaslar:
    for ad in hassaslar:
        print(f"- {ad}")
else:
    print("- (yok)")
EOF
python3 /tmp/env_raporu.py
